<?php
include 'header.php';
require_once '../includes/gemini.php';

$msg_type='';$msg_text='';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { csrf_guard();
    $apiKey=trim((string)($_POST['gemini_api_key']??''));
    $enabled=isset($_POST['gemini_chat_enabled'])?'1':'0';
    $models=gemini_model_options();
    $chatModel=(string)($_POST['gemini_chat_model']??'gemini-3.5-flash');
    $dashboardModel=(string)($_POST['gemini_dashboard_model']??'gemini-3.5-flash');
    $writerModel=(string)($_POST['gemini_writer_model']??'gemini-3.5-flash');
    if(!isset($models[$chatModel]))$chatModel='gemini-3.5-flash';
    if(!isset($models[$dashboardModel]))$dashboardModel='gemini-3.5-flash';
    if(!isset($models[$writerModel]))$writerModel='gemini-3.5-flash';
    $ok=gemini_set_setting($conn,'gemini_api_key',$apiKey,'fas fa-key');
    $ok=gemini_set_setting($conn,'gemini_chat_enabled',$enabled,'fas fa-comments')&&$ok;
    $ok=gemini_set_setting($conn,'gemini_chat_model',$chatModel,'fas fa-robot')&&$ok;
    $ok=gemini_set_setting($conn,'gemini_dashboard_model',$dashboardModel,'fas fa-chart-line')&&$ok;
    $ok=gemini_set_setting($conn,'gemini_writer_model',$writerModel,'fas fa-pen-nib')&&$ok;
    $msg_type=$ok?'success':'error';$msg_text=$ok?'Đã lưu cấu hình Gemini AI.':'Không thể lưu cấu hình AI.';
}
$models=gemini_model_options();
$apiKey=gemini_get_setting($conn,'gemini_api_key','');
$enabled=gemini_get_setting($conn,'gemini_chat_enabled','1');
$chatModel=gemini_get_setting($conn,'gemini_chat_model','gemini-3.5-flash');
$dashboardModel=gemini_get_setting($conn,'gemini_dashboard_model','gemini-3.5-flash');
$writerModel=gemini_get_setting($conn,'gemini_writer_model','gemini-3.5-flash');
?>
