lect name="gemini_writer_model" class="form-control"><?php foreach($models as $id=>$name):?><option value="<?php echo htmlspecialchars($id); ?>" <?php echo $id===$writerModel?'selected':''; ?>><?php echo htmlspecialchars($name); ?></option><?php endforeach;?><?php foreach(gemini_legacy_models() as $id=>$name):?><option value="<?php echo htmlspecialchars($id); ?>" disabled><?php echo htmlspecialchars($name); ?> — đã ngừng API</option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Chatbot ngoài website</label><label class="switch-row"><input type="checkbox" name="gemini_chat_enabled" value="1" <?php echo $enabled==='1'?'checked':''; ?>><span>Bật chatbot Gemini cho khách hàng</span></label></div></div><button class="save-ai" type="submit"><i class="fas fa-floppy-disk"></i> Lưu cấu hình AI</button></form></section><aside class="model-info"><h2 class="card-head"><i class="fas fa-microchip"></i> Model có thể chọn</h2><div class="model-list"><?php foreach($models as $id=>$name):?><div class="model-item"><strong><?php echo htmlspecialchars($name); ?></strong><span><?php echo htmlspecialchars($id); ?></span></div><?php endforeach;?></div><div class="legacy-note"><strong>Gemini 2.0:</strong> source có nhận diện model 2.0 để báo trạng thái legacy, nhưng không đưa vào danh sách sử dụng vì API 2.0 đã ngừng hoạt động. Nên chọn 2.5, 3.1 hoặc model Flash/Flash-Lite mới hơn.</div></aside></div>
